// Campaign ideas: whole campaigns, not single listings. Each idea is built from the cars on this yard today: the cars it uses, a week
// of posts with captions written out, how you'd know it worked, what a person must approve, and a 4:5 key visual drawn in the
// browser. Templates are hand-written; nothing is generated by an AI service, nothing is posted, and every offer needs a person.
import { CFG, $, $$, esc, fmt, json, loadImg, download } from "./core.js";

const M = CFG.market || {};
const DEALER = M.capDealer || CFG.dealer?.name || "the dealership";
const TRIP = { name: "Taupō and back", from: "Auckland", km: 560 };
const money = (n) => "$" + fmt(Math.round(n));
const kmOf = (c) => (c.odometerKm == null ? null : `${fmt(c.odometerKm)} km`);
const name = (c) => `${c.year} ${c.make} ${c.model}`;
const econ = (c) => { const v = c.economy == null ? NaN : Number(typeof c.economy === "object" ? c.economy.value : c.economy); return isFinite(v) && v > 0 ? v : null; };
const summer = () => { const m = new Date().getMonth(); return m >= 10 || m <= 2; };
const uniqModels = (list) => { const seen = new Set(); return list.filter((c) => { const k = c.make + c.model; if (seen.has(k)) return false; seen.add(k); return true; }); };

// ------------------------------------------------------------------------------------------------ the ideas
function ideas(cars, range, brand) {
  const out = [];
  const R = range.find((r) => r.brand === brand) || range[0];

  // 1. the brick reveal
  if (R) {
    const pool = cars.filter((c) => c.make === R.brand), car = pool[Math.floor(pool.length / 2)] || pool[0], other = range.filter((r) => r !== R).slice(0, 2).map((r) => r.brand);
    out.push({ id: "brick", name: "The brick reveal", hook: "Which one is this?", formats: ["Reel · 6 sec", "Carousel", "Story poll"],
      idea: `A ${R.brand} builds itself on the plinth, brick by brick. Followers guess the model in the comments before the last brick lands, and the real car is revealed two days later.`,
      why: "A guessing game asks for a comment, and comments carry a Reel further than likes do. Nobody else on the strip has a brick model of their yard.",
      cars: [car], brand: R.brand, visual: { kind: "brick", src: R.still || R.poster },
      plan: [["Monday", "Reel", `Brick by brick. Which ${R.brand} on our yard is this? Guess in the comments before Wednesday. Right answers go in the draw for a free valet.`],
        ["Wednesday", "Carousel", `It was the ${name(car)}. The bricks on slide one, the real thing on slide two. ${money(car.priceNzd)}${kmOf(car) ? `, ${kmOf(car)}` : ""}. [Number] of you got it.`],
        ["Friday", "Story poll", `Which brand should we build next? ${other[0] || "This one"} or ${other[1] || "that one"}?`]],
      measure: ["Comments per Reel, against your last ten", "Saves and shares", `Enquiries on the ${car.model} within a week of the reveal`],
      approve: "The valet draw needs competition terms and a manager's yes before Monday." });
  }

  // 2. one budget, three lives
  const life = (c) => (/hatch|sedan/.test(c.body) ? "The commute" : /suv|van|wagon/.test(c.body) ? "The school run" : "The weekend away");
  let best = null;
  for (const B of [15000, 20000, 25000, 30000, 35000, 40000, 45000, 50000, 60000]) {
    const near = cars.filter((c) => c.priceNzd >= B * .82 && c.priceNzd <= B * 1.04), lives = {};
    near.forEach((c) => { const l = life(c); if (!lives[l]) lives[l] = c; });
    const n = Object.keys(lives).length; if (n >= 2 && (!best || n > best.n || (n === best.n && near.length > best.m))) best = { B, n, m: near.length, picks: Object.entries(lives) };
  }
  if (best) {
    const P = best.picks.slice(0, 3); best.B = Math.ceil(Math.max(...P.map(([, c]) => c.priceNzd)) / 5000) * 5000;
    out.push({ id: "budget", name: "One budget, three lives", hook: `What ${money(best.B)} buys this week.`, formats: ["Carousel", "Reel", "Story quiz"],
      idea: `Cars at about the same price, each matched to a different week: ${P.map(([l]) => l.toLowerCase()).join(", ")}. One carousel, ${["", "one", "two", "three"][P.length]} ways to spend the same money.`,
      why: "Most buyers start with a number, not a model. 'What does this get me?' is the first question they ask, so answer it before they do.",
      cars: P.map(([, c]) => c), lives: P.map(([l]) => l), visual: { kind: "trio" },
      plan: [["Tuesday", "Carousel", `What ${money(best.B)} buys on our yard this week:\n\n${P.map(([l, c]) => `${l}: ${name(c)}, ${money(c.priceNzd)}`).join("\n")}\n\nWhich week is yours?`],
        ["Thursday", "Reel", "Same money, very different Mondays. Ten seconds on each car, with the price on screen the whole time."],
        ["Saturday", "Story quiz", "Pick your week: the commute, the school run or the weekend away? Answer and we'll send you the car that fits."]],
      measure: ["How many people swipe to the last slide", "Messages that mention a budget", "Test drives on these cars"],
      approve: "Prices must match the live listings on the day it posts." });
  }

  // 3. the trip, by the litre
  const eco = uniqModels(cars.filter((c) => econ(c) && c.fuel !== "electric").sort((a, b) => econ(a) - econ(b))).slice(0, 3);
  if (eco.length >= 2) {
    const L = (c) => Math.round(econ(c) * TRIP.km / 100), s = summer();
    out.push({ id: "trip", name: s ? "Summer road trip, by the litre" : "Long weekend, by the litre", hook: `${TRIP.name} on ${L(eco[0])} litres.`, formats: ["Carousel", "Reel", "Story slider"],
      idea: `Pick a drive everyone in ${TRIP.from} has done, then show what each car on the yard would burn doing it. Real kilometres, real litres, no "great fuel economy".`,
      why: `${s ? "Summer plans are being made right now." : "Long weekends get planned weeks ahead."} A trip people recognise turns an economy figure into something they can picture.`,
      cars: eco, visual: { kind: "number", big: `${L(eco[0])} L`, small: `${TRIP.name}, about ${TRIP.km} km` },
      plan: [["Monday", "Carousel", `${TRIP.from} to ${TRIP.name.replace(" and back", "")} and back, about ${TRIP.km} km. What it takes on our yard:\n\n${eco.map((c) => `${name(c)}: about ${L(c)} litres`).join("\n")}\n\nBased on each car's listed combined economy. Your driving will differ.`],
        ["Wednesday", "Reel", `The whole drive in 15 seconds, with the litres counting up in the corner. Shot on the ${eco[0].model}.`],
        ["Friday", "Story slider", `How many litres does your car use to get to ${TRIP.name.replace(" and back", "")} and back? Slide to guess.`]],
      measure: ["Saves", "Shares, and tags of who they're driving with", "Enquiries on these cars"],
      approve: "The litres come from each listing's combined economy figure. Say so on every post." });
  }

  // 4. will it tow the boat?
  const tow = uniqModels(cars.filter((c) => c.towingKg > 0).sort((a, b) => b.towingKg - a.towingKg)).slice(0, 3);
  if (tow.length >= 2) out.push({ id: "tow", name: "Will it tow the boat?", hook: "Will it tow the boat?", formats: ["Story questions", "Reel", "Carousel"],
    idea: "Ask followers what they need to tow this summer, then answer each one with a car on the yard and its braked towing rating.",
    why: "A real question from a real follower gets watched to the end. And everyone who tows has a very specific number in their head.",
    cars: tow, visual: { kind: "number", big: `${fmt(tow[0].towingKg)} kg`, small: `braked towing, ${tow[0].make} ${tow[0].model}` },
    plan: [["Monday", "Story question box", "What are you towing this summer? Boat, caravan, horse float, a trailer of firewood. Tell us and we'll match you a car."],
      ["Wednesday", "Reel", `"Will it tow a 2-tonne boat?" The ${name(tow[0])} is rated to ${fmt(tow[0].towingKg)} kg braked. Here's how it sits hitched up.`],
      ["Friday", "Carousel", `Tow ratings on the yard right now:\n\n${tow.map((c) => `${name(c)}: ${fmt(c.towingKg)} kg braked`).join("\n")}`]],
    measure: ["Question-box replies", "Ute and SUV enquiries", "Saves"],
    approve: "Check every rating against the maker's spec for that exact variant before it posts." });

  // 5. first car, fully checked
  const first = uniqModels(cars.filter((c) => /hatch|sedan/.test(c.body)).sort((a, b) => a.priceNzd - b.priceNzd)).slice(0, 3);
  if (first.length >= 2) {
    const cap = Math.ceil(Math.max(...first.map((c) => c.priceNzd)) / 1000) * 1000;
    out.push({ id: "first", name: "First car, fully checked", hook: "Their first car. Your checklist.", formats: ["Carousel", "Reel", "Story"],
      idea: `A carousel for parents of new drivers: the five checks worth doing on any first car, then cars under ${money(cap)} the workshop has put through all five.`,
      why: "Parents do the research and often pay. A checklist gets saved and sent to the family group chat, which is where this decision actually gets made.",
      cars: first, visual: { kind: "list", lines: ["Warrant of fitness", "Service history", "Tyres", "Safety rating", "Insurance for a learner"] },
      plan: [["Tuesday", "Carousel", `Five checks before a first car:\n1. Warrant of fitness date\n2. Service history\n3. Tyre tread and age\n4. Safety rating\n5. Insurance cost for a learner\n\nThen: ${first.map((c) => `${name(c)}, ${money(c.priceNzd)}`).join("; ")}. All checked against the five.`],
        ["Thursday", "Reel", `Our technician runs the five checks on the ${first[0].model} in 30 seconds.`],
        ["Sunday", "Story", "New driver at home? Reply 'checklist' and we'll send you the five checks."]],
      measure: ["Saves and shares", "Replies asking for the checklist", "Test drives booked by parents"],
      approve: "Only show results from real inspections. Safety ratings come from rightcar.govt.nz for the exact model and year." });
  }

  // 6. keys day
  const fresh = cars.slice().sort((a, b) => b.year - a.year)[0];
  out.push({ id: "keys", name: "Keys day", hook: "Keys day.", formats: ["Story", "Reel", "Post"],
    idea: "Every handover gets one photo: the new owner, their car and where they're driving first. At the end of the month, every set of keys becomes one Reel.",
    why: "Buyers trust other buyers. A month of real handovers says more about the yard than any ad can.",
    cars: fresh ? [fresh] : [], visual: { kind: "photo" },
    plan: [["Every handover", "Story", `Keys day for [first name]. First stop: [where they're headed]. Enjoy the ${fresh ? fresh.model : "new car"}.`],
      ["Month end", "Reel", "Every set of keys we handed over this month, in 20 seconds."],
      ["Month end", "Post", `Thank you to everyone who drove away from ${DEALER} this month. See you at the first service.`]],
    measure: ["Tags and shares by new owners", "Profile visits", "Referrals that mention the Reel"],
    approve: "Written consent from every customer before their photo is used. First names only, no number plates." });

  // 7. ask the workshop
  const brake = (CFG.parts?.track || []).find((p) => p.k === "brake");
  out.push({ id: "workshop", name: "Ask the workshop", hook: "Ask the workshop.", formats: ["Story question", "Reel", "Carousel"],
    idea: "One customer question, one technician, thirty seconds, every week. Start with the questions the service desk hears most.",
    why: "Most people only meet the service team when something has gone wrong. A weekly answer makes the workshop someone they know before they need it.",
    cars: [], visual: brake ? { kind: "brick", src: brake.still } : { kind: "photo" },
    plan: [["Monday", "Story question", "Got a question about your car? A technician answers one every Thursday."],
      ["Thursday", "Reel", "'How long do brake pads last?' Answered in 30 seconds, with an old pad in hand."],
      ["Saturday", "Carousel", "This week's three questions, answered by the workshop."]],
    measure: ["Service bookings that mention the videos", "Question replies", "New follows"],
    approve: "The technician agrees to appear. The service manager checks every answer before it posts." });

  // 8. EV questions at the charger
  const ev = uniqModels(cars.filter((c) => c.fuel === "electric" || /hybrid/.test(c.fuel))).slice(0, 3);
  if (ev.length) out.push({ id: "ev", name: "Ask us at the charger", hook: "Ask us at the charger.", formats: ["Reel", "Story poll", "Carousel"],
    idea: `Park the ${ev[0].make} ${ev[0].model} at a public charger and answer one real question per clip: range in winter, battery life, what it costs to run.`,
    why: "People who are nearly ready to go electric have one or two worries left. Answer those, on camera, where the worry lives.",
    cars: ev, visual: { kind: "photo" },
    plan: [["Monday", "Reel", `"How far does it really go in winter?" Answered at the charger with the ${name(ev[0])}.`],
      ["Wednesday", "Story poll", "What stops you going electric? Range, price or charging at home?"],
      ["Friday", "Carousel", "The three questions we got most this week, answered."]],
    measure: ["Poll answers (they tell you the next video)", "EV and hybrid enquiries", "Watch time"],
    approve: "Every range and battery claim must cite the car's own specification." });

  // 9. the club car wash
  out.push({ id: "club", name: "The club car wash", hook: "Bring your car. Fund the club.", formats: ["Post with the club", "Stories", "Reel"],
    idea: "Hand the yard to a local club for a Saturday car-wash fundraiser. The dealership covers the water, the soap and a sausage sizzle; the club keeps every dollar.",
    why: "It puts the dealership in the club's channels, not just its own. Families share it because it's their club, not because it's an ad.",
    cars: [], visual: { kind: "photo" },
    plan: [["Two weeks out", "Post with the club", "Saturday, 9 till 1: the [club name] car wash at our yard. Every dollar goes to the club. Bring the muddiest car you've got."],
      ["On the day", "Stories", "The queue, the sizzle and the running total, updated every hour."],
      ["After", "Reel", "We raised $[total] for [club name]. Thanks for all the dirty cars."]],
    measure: ["Reach and shares through the club's pages", "New followers from the area", "People on the yard that day"],
    approve: "An agreement with the club, and parental consent for anyone under 18 who appears." });
  return out;
}

// ------------------------------------------------------------------------------------------------ the key visual, 1080 × 1350
async function paint(cv, it, cars, T) {
  const W = 1080, H = 1350, ctx = cv.getContext("2d"); cv.width = W; cv.height = H;
  await (document.fonts ? document.fonts.ready : Promise.resolve());
  const img = async (s) => { try { return s ? await loadImg(s) : null; } catch (e) { return null; } };
  const cover = (im, x, y, w, h) => { if (!im) return; const s = Math.max(w / im.naturalWidth, h / im.naturalHeight), sw = w / s, sh = h / s; ctx.drawImage(im, (im.naturalWidth - sw) / 2, (im.naturalHeight - sh) / 2, sw, sh, x, y, w, h); };
  const F = (size, font) => { const [w, ...f] = font.split(" "); return `${w} ${size}px ${f.join(" ")}`; };
  const text = (s, x, y, size, font, colour, align = "left", ls = 0) => { ctx.font = F(size, font); ctx.fillStyle = colour; ctx.textAlign = align; try { ctx.letterSpacing = ls + "px"; } catch (e) { } ctx.fillText(s, x, y); try { ctx.letterSpacing = "0px"; } catch (e) { } };
  const wrap = (s, max, size, font) => { ctx.font = F(size, font); const out = []; let line = ""; for (const w of String(s).split(/\s+/)) { const t = line ? line + " " + w : w; if (ctx.measureText(t).width > max && line) { out.push(line); line = w; } else line = t; } if (line) out.push(line); return out; };
  const sans = `"Instrument Sans", system-ui, sans-serif`, serif = `"Instrument Serif", Georgia, serif`, mono = `"IBM Plex Mono", ui-monospace, monospace`;
  ctx.fillStyle = T.paper; ctx.fillRect(0, 0, W, H);
  // picture band
  const py = 330, ph = 760, v = it.visual || {};
  if (v.kind === "brick") { cover(await img(v.src), 0, py, W, ph); }
  else if (v.kind === "trio") { const C = it.cars.slice(0, 3), ims = await Promise.all(C.map((c) => img(c.img.card))), g = 12, h = (ph - g * (C.length - 1)) / C.length, iw = Math.round(h * 4 / 3);
    C.forEach((c, i) => { const y = py + i * (h + g); ctx.fillStyle = T.chalk; ctx.fillRect(0, y, W, h); cover(ims[i], 0, y, iw, h);
      text((it.lives && it.lives[i] || "").toUpperCase(), iw + 44, y + h / 2 - 46, 22, `500 ${mono}`, T.rose, "left", 2);
      text(c.model, iw + 44, y + h / 2 + 10, 50, `500 ${sans}`, T.ink, "left", -1.5); text(`${c.year} · ${money(c.priceNzd)}`, iw + 44, y + h / 2 + 56, 28, `400 ${mono}`, T.body); }); }
  else if (v.kind === "list") { ctx.fillStyle = T.deep; ctx.fillRect(0, py, W, ph); v.lines.forEach((l, i) => { text(String(i + 1).padStart(2, "0"), 80, py + 130 + i * 128, 30, `400 ${mono}`, T.champ); text(l, 170, py + 132 + i * 128, 56, `500 ${sans}`, "#F5F2ED", "left", -1); }); }
  else { const c = it.cars[0]; ctx.fillStyle = T.chalk; ctx.fillRect(0, py, W, ph); cover(await img(c && (c.img.room || c.img.card)), 0, py, W, ph);
    if (v.kind === "number") { ctx.fillStyle = "rgba(20,18,22,.62)"; ctx.fillRect(0, py + ph - 230, W, 230); text(v.big, 72, py + ph - 92, 128, `400 ${serif}`, "#F5F2ED", "left", -2); text(v.small, 72, py + ph - 40, 28, `400 ${mono}`, "rgba(245,242,237,.8)"); } }
  // headline and kicker
  text(`CAMPAIGN IDEA · ${it.formats[0].toUpperCase()}`, 72, 104, 26, `500 ${mono}`, T.rose, "left", 3);
  wrap(it.hook, W - 144, 96, `500 ${sans}`).slice(0, 2).forEach((l, i) => text(l, 72, 210 + i * 98, 96, `500 ${sans}`, T.ink, "left", -3));
  // foot
  text(DEALER, 72, H - 150, 40, `400 ${serif}`, T.ink);
  wrap(it.name, W - 144, 30, `400 ${sans}`).slice(0, 1).forEach((l) => text(l, 72, H - 100, 30, `400 ${sans}`, T.body));
  text(CFG.campaignTruth || "Idea · draft · not posted", W - 72, H - 56, 22, `500 ${mono}`, T.rose, "right", 1.5);
  ctx.fillStyle = T.line; ctx.fillRect(72, H - 200, W - 144, 2);
}

async function copyText(s) { try { await navigator.clipboard.writeText(s); return true; } catch (e) { const t = document.createElement("textarea"); t.value = s; t.style.position = "fixed"; t.style.opacity = "0"; document.body.appendChild(t); t.select(); let ok = false; try { ok = document.execCommand("copy"); } catch (e2) { } t.remove(); return ok; } }

export async function initCampaigns() {
  const host = $("#cp"); if (!host) return;
  const cars = (await json(CFG.stockUrl)).cars;
  const cs = getComputedStyle(document.documentElement), tok = (k, d) => (cs.getPropertyValue(k) || d).trim() || d;
  const T = { paper: tok("--paper", "#F5F2ED"), chalk: tok("--chalk", "#E8E2D9"), ink: tok("--ink", "#1A1A1E"), deep: tok("--deep", "#1A1A1E"), body: tok("--body", "#4A4950"), rose: tok("--rose", "#7C7486"), champ: tok("--champ", "#CDB591"), line: "rgba(26,26,30,.14)" };
  const range = (window.__range || (CFG.range?.items || []).map((r) => ({ ...r }))).filter((r) => cars.some((c) => c.make === r.brand));
  let brand = range[0]?.brand, list = ideas(cars, range, brand), cur = list[0]?.id;
  const L = $("#cpList"), card = $("#cpCard"), cv = $("#cpCv");
  const draw = () => {
    list = ideas(cars, range, brand); const it = list.find((x) => x.id === cur) || list[0]; cur = it.id;
    L.innerHTML = list.map((x, i) => `<button type="button" role="tab" id="cpt-${x.id}" aria-selected="${x.id === cur}" aria-controls="cpCard" data-id="${x.id}"><span class="n">${String(i + 1).padStart(2, "0")}</span><span><b>${esc(x.name)}</b><span>${esc(x.formats.join(" · "))}</span></span></button>`).join("");
    card.setAttribute("aria-labelledby", "cpt-" + it.id);
    $("#cpTxt").innerHTML = `<p class="cp-hook">${esc(it.hook)}</p>
      ${it.id === "brick" && range.length > 1 ? `<label class="cp-brand"><span class="label">Brand</span><select id="cpBrand">${range.map((r) => `<option${r.brand === brand ? " selected" : ""}>${esc(r.brand)}</option>`).join("")}</select></label>` : ""}
      <div class="cp-blk"><span class="label">The idea</span><p>${esc(it.idea)}</p></div>
      <div class="cp-blk"><span class="label">Why it works</span><p>${esc(it.why)}</p></div>
      ${it.cars.length ? `<div class="cp-blk"><span class="label">Cars it uses</span><div class="cp-cars">${it.cars.map((c) => `<button type="button" data-car="${esc(c.id)}"><img src="${esc(c.img.card)}" alt="" loading="lazy" decoding="async"><span>${esc(name(c))}<i>${money(c.priceNzd)}</i></span></button>`).join("")}</div></div>` : ""}
      <div class="cp-blk"><span class="label">The week, written</span><ol class="cp-plan">${it.plan.map(([d, f, cap], i) => `<li><div class="cp-when"><b>${esc(d)}</b><span>${esc(f)}</span></div><p id="cpc-${i}">${esc(cap).replace(/\n/g, "<br>")}</p><button class="btn ghost sm" type="button" data-copy="${i}">Copy</button></li>`).join("")}</ol></div>
      <div class="cp-blk"><span class="label">How you'll know it worked</span><ul class="cp-measure">${it.measure.map((m) => `<li>${esc(m)}</li>`).join("")}</ul></div>
      <p class="cp-approve"><b>Needs a person:</b> ${esc(it.approve)}</p>`;
    paint(cv, it, cars, T).catch((e) => console.warn("campaign visual", e));
    cv.setAttribute("aria-label", `Key visual for ${it.name}: ${it.hook}`);
  };
  L.addEventListener("click", (e) => { const b = e.target.closest("[data-id]"); if (b) { cur = b.dataset.id; draw(); } });
  L.addEventListener("keydown", (e) => { if (!/Arrow(Up|Down)/.test(e.key)) return; e.preventDefault(); const i = list.findIndex((x) => x.id === cur), j = (i + (e.key === "ArrowDown" ? 1 : -1) + list.length) % list.length; cur = list[j].id; draw(); $(`#cpt-${cur}`).focus(); });
  card.addEventListener("change", (e) => { if (e.target.id === "cpBrand") { brand = e.target.value; draw(); } });
  card.addEventListener("click", async (e) => {
    const c = e.target.closest("[data-car]"); if (c) { dispatchEvent(new CustomEvent("stock:pick", { detail: c.dataset.car })); window.__stockPick = c.dataset.car; setTimeout(() => ($("#spot") && !$("#spot").hidden ? $("#spot") : $("#stock")).scrollIntoView({ behavior: "smooth", block: "center" }), 60); return; }
    const k = e.target.closest("[data-copy]"); if (k) { const ok = await copyText($(`#cpc-${k.dataset.copy}`).innerText); k.textContent = ok ? "Copied" : "Select and copy"; setTimeout(() => (k.textContent = "Copy"), 1600); }
  });
  $("#cpDl").onclick = () => { const it = list.find((x) => x.id === cur); cv.toBlob((b) => b && download(b, `${M.filePrefix || "campaign"}-${it.id}.png`), "image/png"); };
  $("#cpAll").onclick = async (e) => { const it = list.find((x) => x.id === cur); const s = [`${it.name}: ${it.hook}`, "", it.idea, "", ...it.plan.map(([d, f, cap]) => `${d} · ${f}\n${cap}\n`), `Measure: ${it.measure.join("; ")}`, `Needs a person: ${it.approve}`].join("\n");
    const ok = await copyText(s); e.currentTarget.textContent = ok ? "Plan copied" : "Couldn't copy"; setTimeout(() => ($("#cpAll").textContent = "Copy the whole plan"), 1600); };
  addEventListener("campaign:open", (e) => { const d = e.detail || {}; if (d.brand) brand = d.brand; if (d.id) cur = d.id; draw(); });
  if (window.__campaign) { const d = window.__campaign; if (d.brand) brand = d.brand; if (d.id) cur = d.id; }
  draw();
}
